@Composable
private fun TacticalRadarScanHud(
    hasLocation: Boolean,
    lat: Double?,
    lng: Double?,
    radarColor: Color
) {
    val infiniteTransition = rememberInfiniteTransition(label = "radarRotation")
    val rotation by infiniteTransition.animateFloat(
        initialValue = 0f,
        targetValue = 360f,
        animationSpec = infiniteRepeatable(
            animation = tween(4000, easing = LinearEasing),
            repeatMode = RepeatMode.Restart
        ),
        label = "radarSweep"
    )

    val pulseScale by infiniteTransition.animateFloat(
        initialValue = 0.92f,
        targetValue = 1.08f,
        animationSpec = infiniteRepeatable(
            animation = tween(1000, easing = FastOutSlowInEasing),
            repeatMode = RepeatMode.Reverse
        ),
        label = "radarIconPulse"
    )

    Column(
        horizontalAlignment = Alignment.CenterHorizontally,
        modifier = Modifier.fillMaxWidth()
    ) {
        Box(
            modifier = Modifier.size(200.dp),
            contentAlignment = Alignment.Center
        ) {
            // Animated Sweeping Radar Canvas
            Canvas(modifier = Modifier.fillMaxSize()) {
                val center = Offset(size.width / 2f, size.height / 2f)
                val radius = size.minDimension / 2f

                // Concentric Range Rings
                drawCircle(
                    color = radarColor.copy(alpha = 0.15f),
                    radius = radius,
                    style = Stroke(width = 1.5f)
                )
                drawCircle(
                    color = radarColor.copy(alpha = 0.25f),
                    radius = radius * 0.66f,
                    style = Stroke(width = 1.2f)
                )
                drawCircle(
                    color = radarColor.copy(alpha = 0.35f),
                    radius = radius * 0.33f,
                    style = Stroke(width = 1f)
                )

                // Crosshairs
                drawLine(
                    color = radarColor.copy(alpha = 0.15f),
                    start = Offset(center.x, 0f),
                    end = Offset(center.x, size.height),
                    strokeWidth = 1f
                )
                drawLine(
                    color = radarColor.copy(alpha = 0.15f),
                    start = Offset(0f, center.y),
                    end = Offset(size.width, center.y),
                    strokeWidth = 1f
                )
            }

            // Rotating Sweep Beam
            Box(
                modifier = Modifier
                    .size(190.dp)
                    .graphicsLayer { rotationZ = rotation }
            ) {
                Canvas(modifier = Modifier.fillMaxSize()) {
                    drawArc(
                        brush = Brush.sweepGradient(
                            listOf(
                                Color.Transparent,
                                radarColor.copy(alpha = 0.45f)
                            )
                        ),
                        startAngle = 0f,
                        sweepAngle = 55f,
                        useCenter = true
                    )
                }
            }

            // Pulsing Center Distress Beacon
            Surface(
                modifier = Modifier
                    .size(68.dp)
                    .graphicsLayer {
                        scaleX = pulseScale
                        scaleY = pulseScale
                    }
                    .shadow(
                        elevation = 16.dp,
                        shape = CircleShape,
                        ambientColor = radarColor,
                        spotColor = radarColor
                    ),
                shape = CircleShape,
                color = radarColor,
                contentColor = Color.White,
                border = BorderStroke(2.dp, Color.White.copy(alpha = 0.5f))
            ) {
                Box(contentAlignment = Alignment.Center) {
                    Icon(
                        imageVector = Icons.Default.Warning,
                        contentDescription = null,
                        modifier = Modifier.size(34.dp),
                        tint = Color.White
                    )
                }
            }
        }

        Spacer(Modifier.height(14.dp))

        // Coordinates & Telemetry Chip
        Row(
            horizontalArrangement = Arrangement.spacedBy(8.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            Surface(
                shape = RoundedCornerShape(8.dp),
                color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.6f),
                border = BorderStroke(1.dp, MaterialTheme.colorScheme.onSurface.copy(alpha = 0.1f))
            ) {
                Row(
                    modifier = Modifier.padding(horizontal = 8.dp, vertical = 4.dp),
                    verticalAlignment = Alignment.CenterVertically
