internal fun formatCoordinate(coord: Double, isLat: Boolean): String {
    val dir = if (isLat) {
        if (coord >= 0) "N" else "S"
    } else {
        if (coord >= 0) "E" else "W"
    }
    return String.format(Locale.US, "%.5f° %s", kotlin.math.abs(coord), dir)
}

